40→          rgba(180, 92, 38, calc(0.22 * var(--warm))) 0%,
          transparent 62%),
        radial-gradient(ellipse 70% 50% at 50% 78%,
          rgba(42, 22, 12, 0.9) 0%,
          transparent 58%),
        radial-gradient(ellipse 120% 80% at 50% 100%,
          #120c09 0%,
          #070504 55%);
    }

50→    .vignette {
      position: absolute;
      inset: 0;
      pointer-events: none;
      background:
