      z-index: 6;
    }

60→    .glow {
      position: absolute;
      width: min(90vmin, 820px);
      height: min(90vmin, 820px);
      left: 50%;
      top: 52%;
      transform: translate(-50%, -50%);
      background:
        radial-gradient(circle at 50% 58%,
          rgba(232, 140, 62, 0.16) 0%,
70→          rgba(160, 70, 22, 0.08) 28%,
          transparent 58%);
      filter: blur(8px);
      pointer-events: none;
      z-index: 0;
      animation: breathe 7.5s ease-in-out infinite;
    }

    .table {
      position: absolute;
80→      width: min(140vmin, 1400px);
      height: 38%;
      left: 50%;
      bottom: 0;
      transform: translateX(-50%);
      background:
        radial-gradient(ellipse 70% 55% at 50% 0%,
          rgba(28, 16, 10, 0.95) 0%,
          rgba(10, 7, 5, 0) 70%);
      pointer-events: none;
90→      z-index: 0;
    }

    .stage {
      position: relative;
